#!/usr/bin/env bash
set -euo pipefail

# Collect only the CatOS packages and the signed index generated by the SDK.
# Usage: assemble-apk-feed.sh SDK_PACKAGES_DIR SITE_DIR RELEASE ARCH

if [[ $# -ne 4 ]]; then
  printf 'Usage: %s SDK_PACKAGES_DIR SITE_DIR RELEASE ARCH\n' "$0" >&2
  exit 2
fi

source_dir="$1"
site_dir="$2"
release="$3"
arch="$4"

for value in "$release" "$arch"; do
  if [[ ! "$value" =~ ^[A-Za-z0-9][A-Za-z0-9._-]*$ ]]; then
    printf 'Invalid release or architecture: %s\n' "$value" >&2
    exit 2
  fi
done

if [[ ! -d "$source_dir" ]]; then
  printf 'Missing SDK package directory: %s\n' "$source_dir" >&2
  exit 1
fi

packages=(
  catos-notify
  catos-ddns
  catos-acme
  luci-app-catos-notify
  luci-app-catos-ddns
  luci-app-catos-acme
)

shopt -s nullglob
matches=()

while IFS= read -r -d '' index; do
  package_dir="$(dirname "$index")"
  valid=1

  for package in "${packages[@]}"; do
    files=("${package_dir}/${package}-"*.apk)
    if [[ ${#files[@]} -ne 1 || ! -s "${files[0]:-}" ]]; then
      valid=0
      break
    fi
  done

  if [[ $valid -eq 1 ]]; then
    matches+=("$package_dir")
  fi
done < <(find "$source_dir" -type f -name packages.adb -print0)

if [[ ${#matches[@]} -ne 1 ]]; then
  printf 'Expected exactly one SDK feed containing all six CatOS APKs, found %s.\n' "${#matches[@]}" >&2
  exit 1
fi

package_dir="${matches[0]}"

# Fail closed: do not accidentally publish packages from OpenWrt's other feeds.
archives=("$package_dir"/*.apk)
if [[ ${#archives[@]} -ne ${#packages[@]} ]]; then
  printf 'SDK feed has %s APKs; expected only the six CatOS packages.\n' "${#archives[@]}" >&2
  exit 1
fi

if [[ ! -s "$package_dir/packages.adb" ]]; then
  printf 'The SDK did not produce a nonempty packages.adb index.\n' >&2
  exit 1
fi

destination="${site_dir}/releases/${release}/${arch}"
if [[ -e "$destination" ]]; then
  printf 'Refusing to replace an existing feed directory: %s\n' "$destination" >&2
  exit 1
fi

mkdir -p "$destination"
cp "$package_dir/packages.adb" "$destination/"
cp "${archives[@]}" "$destination/"

(
  cd "$destination"
  sha256sum packages.adb ./*.apk > SHA256SUMS
  sha256sum --check SHA256SUMS
)

printf 'Prepared %s with %s APKs and a signed-index artifact.\n' "$destination" "${#archives[@]}"
